// Banner data (src/banners.json) is generated by scripts/sync-banners.mjs
// from the UIGF org's CurrentBannerWatcher dataset, which follows
// HoYoverse's official announcements. A scheduled GitHub Action keeps it
// current; do not edit src/banners.json by hand. Editorial fields
// (pairings, tier overrides, art nudges) live in src/banner-meta.json and
// are merged in by the sync.
import bannerData from './banners.json'
import upcomingData from './upcoming.json'
import type { Banner, UpcomingBanner } from './types'

export const BANNERS = bannerData as Banner[]

// Announced characters without a banner date yet (src/upcoming.json).
// Curated by hand, pruned by the banner sync once they get a real banner.
export const UPCOMING = upcomingData as UpcomingBanner[]

// "Raiden Shogun" → "raiden-shogun", the slug used in share links.
export function bannerSlug(name: string): string {
  return name.toLowerCase().replace(/\s+/g, '-')
}

// "2026-11-24" becomes "Nov 24": ISO dates are for data, not for people.
export function formatDate(iso: string): string {
  const date = new Date(`${iso}T00:00:00`)
  return new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric' }).format(date)
}

// "2026-11-24" becomes "Nov 24, 2026": the share card stamps the banner
// window with a year, since the card outlives its screen context.
export function formatDateYear(iso: string): string {
  const date = new Date(`${iso}T00:00:00`)
  return new Intl.DateTimeFormat('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  }).format(date)
}

// Exact phase windows use startsAt/endsAt (ISO with offset). Data without
// them falls back to whole local days, which is how the hand-written list
// used to behave. Both start and end are inclusive.
function bannerStart(banner: Banner): number {
  return banner.startsAt
    ? Date.parse(banner.startsAt)
    : Date.parse(`${banner.startDate}T00:00:00`)
}

function bannerEnd(banner: Banner): number {
  return banner.endsAt
    ? Date.parse(banner.endsAt)
    : Date.parse(`${banner.endDate}T23:59:59`)
}

/** Has the banner's end time passed? */
export function bannerEnded(banner: Banner, now: number = Date.now()): boolean {
  return now > bannerEnd(banner)
}

/** 'starts Nov 24' before, 'ends Nov 24' during, 'ended Nov 24' after. */
export function bannerDateLabel(banner: Banner, now: number = Date.now()): string {
  if (now < bannerStart(banner)) return `starts ${formatDate(banner.startDate)}`
  if (now > bannerEnd(banner)) return `ended ${formatDate(banner.endDate)}`
  return `ends ${formatDate(banner.endDate)}`
}

/** The banner the site judges against by default: the live banner that
 *  started most recently (a phase change can overlap on the changeover
 *  day, and the new phase should win), else the next one to start, else
 *  the one that ended most recently. */
export function activeBanner(list: Banner[] = BANNERS, now: number = Date.now()): Banner {
  const live = list.filter((banner) => bannerStart(banner) <= now && now <= bannerEnd(banner))
  if (live.length > 0) {
    return live.reduce((latest, banner) =>
      bannerStart(banner) > bannerStart(latest) ? banner : latest,
    )
  }
  const upcoming = list
    .filter((banner) => bannerStart(banner) > now)
    .sort((a, b) => bannerStart(a) - bannerStart(b))[0]
  if (upcoming) return upcoming
  return [...list].sort((a, b) => bannerEnd(b) - bannerEnd(a))[0] ?? list[0]
}

/** Pick a banner by URL slug (e.g. "?b=furina" or "?b=mitya"); an absent
 *  or unknown slug falls back to the active one. The share pages use
 *  this so the preview card matches the banner the sharer judged. */
export function bannerBySlug(
  slug: string | null | undefined,
  list: Banner[] = BANNERS,
): Banner {
  if (slug) {
    const wanted = slug.toLowerCase()
    const found = list.find((banner) => bannerSlug(banner.character) === wanted)
    if (found) return found
  }
  return activeBanner(list)
}

// "7.3" becomes 7003 so versions sort numerically, not as strings. Entries
// with no announced version sort last.
function versionRank(version: string | undefined): number {
  const match = /^(\d+)(?:\.(\d+))?$/.exec(version ?? '')
  if (!match) return Number.POSITIVE_INFINITY
  return Number(match[1]) * 1000 + Number(match[2] ?? 0)
}

/** Announced characters still waiting for a dated banner. The sync prunes
 *  src/upcoming.json as phases are published, but a character can also
 *  appear in the dated list first, so filter here too rather than show a
 *  name twice. Ordered by version, then alphabetically. */
export function upcomingBanners(
  dated: Banner[] = BANNERS,
  upcoming: UpcomingBanner[] = UPCOMING,
): UpcomingBanner[] {
  const datedNames = new Set(dated.map((banner) => banner.character))
  return upcoming
    .filter((entry) => !datedNames.has(entry.character))
    .sort((a, b) => {
      const rank = versionRank(a.version) - versionRank(b.version)
      return rank || a.character.localeCompare(b.character)
    })
}
